import Link from "next/link";
import {
  ArrowRight01Icon,
  DashboardCircleIcon,
} from "@hugeicons/core-free-icons";
import { HugeiconsIcon } from "@hugeicons/react";
import { Button } from "@/components/ui/button";

export default function Home() {
  return (
    <div className="relative isolate flex min-h-svh flex-col items-center justify-center overflow-hidden bg-background">
      {/* Background decoration */}
      <div className="absolute inset-0 -z-10 h-full w-full bg-[radial-gradient(#e5e7eb_1px,transparent_1px)] bg-size-[16px_16px] mask-[radial-gradient(ellipse_50%_50%_at_50%_50%,#000_70%,transparent_100%)] dark:bg-[radial-gradient(#ffffff15_1px,transparent_1px)]" />

      <div className="container relative z-10 mx-auto flex flex-col items-center px-4 text-center">
        {/* Badge */}
        <div className="mb-6 inline-flex items-center gap-2 rounded-full border border-primary/20 bg-primary/5 px-4 py-1.5 text-sm font-medium text-primary backdrop-blur-sm">
          <HugeiconsIcon
            icon={DashboardCircleIcon}
            size={16}
            strokeWidth={1.5}
          />
          <span>Murgodash Playground</span>
        </div>

        {/* Hero Title */}
        <h1 className="max-w-3xl font-heading text-4xl font-bold tracking-tight text-foreground sm:text-6xl">
          Le template <span className="text-primary">Bento</span> ultime pour
          vos tableaux de bord.
        </h1>

        {/* Description */}
        <p className="mt-6 max-w-xl text-lg text-muted-foreground">
          Une architecture moderne basée sur Next.js 15, Tailwind v4 et
          Hugeicons. Prêt à l'emploi, hautement personnalisable et conçu pour la
          performance.
        </p>

        {/* CTA */}
        <div className="mt-10 flex items-center justify-center">
          <Button
            asChild
            size="lg"
            className="h-12 rounded-full px-8 text-base shadow-lg shadow-primary/20"
          >
            <Link href="/dashboard" className="flex items-center gap-2">
              Aller vers le Dashboard
              <HugeiconsIcon
                icon={ArrowRight01Icon}
                size={18}
                strokeWidth={1.5}
              />
            </Link>
          </Button>
        </div>

        {/* Footer info (subtle) */}
        <div className="mt-20 flex flex-wrap justify-center gap-x-8 gap-y-4 text-sm text-muted-foreground/60">
          <div className="flex items-center gap-1.5">
            <span className="h-1.5 w-1.5 rounded-full bg-emerald-500" />
            Next.js 15+
          </div>
          <div className="flex items-center gap-1.5">
            <span className="h-1.5 w-1.5 rounded-full bg-blue-500" />
            Tailwind v4
          </div>
          <div className="flex items-center gap-1.5">
            <span className="h-1.5 w-1.5 rounded-full bg-orange-500" />
            HugeIcons
          </div>
        </div>
      </div>
    </div>
  );
}
